}{ "entries": [] }{ "entries": [] }{"entries":[{"dz":"DZ402","name_han":"黄庭内外玉景经解（蒋慎修）","name_vi":"Hoàng Đình Nội Ngoại Ngọc Cảnh Kinh Giải (Tưởng Thận Tu)","bu":"洞玄","author":"蒋慎修","era":"北宋","topic":"注疏","essence":"Bản chú giải tàn khuyết về Hoàng Đình nội–ngoại cảnh, chú trọng đan đạo âm dương và thành tiên tự nhiên. Phần còn lại chủ yếu chú chương 28–30 nội cảnh, gắn thân trung chi thần với tu luyện. Là một trong ít chú sớ Hoàng Đình khác hệ Lương Khâu Tử trong Chính thống Đạo tạng.","key_text":"黄者，中央之色也；庭者，四方之中也。","use":"Đối chiếu chú Hoàng Đình theo hướng nội đan và tồn thần.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%BA%AD%E5%85%A7%E5%A4%96%E7%8E%89%E6%99%AF%E7%B6%93%E8%A7%A3%EF%BC%88%E8%94%A3%E6%85%8E%E4%BF%AE%EF%BC%89&variant=zh-hans","https://ctext.org/wiki.pl?if=gb&res=708676&remap=gb","https://www.shidianguji.com/book/DZ0403"],"textual_certainty":"high"},{"dz":"DZ1389","name_han":"太上黄庭中景经（李千乘注）","name_vi":"Thái Thượng Hoàng Đình Trung Cảnh Kinh (Lý Thiên Thừa chú)","bu":"正一","author":"李千乘","era":"隋唐","topic":"注疏","essence":"Kinh và chú về Hoàng Đình trung cảnh, mô tả vị trí–hình–sắc–thần các tạng phủ và quan khiếu. Chú giải danh từ và nghĩa kinh để hỗ trợ tồn tư thân trung chư thần. Bổ sung hệ nội–ngoại cảnh bằng lớp “trung cảnh”.","key_text":"合乾坤，定六府，知机真神，穷理尽性。","use":"Học tồn thần và đối chiếu ba tầng Hoàng Đình.","sources":["https://zh.daoinfo.org/index.php?title=%E5%A4%AA%E4%B8%8A%E9%BB%83%E5%BA%AD%E4%B8%AD%E6%99%AF%E7%B6%93%EF%BC%88%E6%9D%8E%E5%8D%83%E4%B9%98%E6%B3%A8%E6%9C%AC%EF%BC%89&variant=zh-hans","https://zh.wikisource.org/zh-hans/%E6%AD%A3%E7%B5%B1%E9%81%93%E8%97%8F"],"textual_certainty":"high"},{"dz":"DZ092","name_han":"元始无量度人上品妙经注解（薛季昭）","name_vi":"Nguyên Thủy Vô Lượng Độ Nhân Thượng Phẩm Diệu Kinh Chú Giải (Tiết Quý Chiêu)","bu":"洞真","author":"薛季昭","era":"元（大德）","topic":"注疏","essence":"Chú Độ Nhân Kinh theo hướng cổ chú, giải chữ nghĩa và chương cú rõ ràng, dễ tụng đọc. Không nghiêng mạnh nội đan như các chú Nam Tống, mà tổng hợp tiền nhân thành một nhà. Có tiến kinh biểu và hậu ký về dòng truyền.","key_text":"天不爱道，世得见经。","use":"Nhập môn tụng và hiểu nghĩa đen Độ Nhân Kinh.","sources":["https://zh.daoinfo.org/index.php?title=%E5%85%83%E5%A7%8B%E7%84%A1%E9%87%8F%E5%BA%A6%E4%BA%BA%E4%B8%8A%E5%93%81%E5%A6%99%E7%B6%93%E8%A8%BB%E8%A7%A3&variant=zh-hans","https://www.shidianguji.com/book/DZ0092","http://www.ctcwri.idv.tw/CTCW-CMTS/CMT01%E6%B4%9E%E7%9C%9F%E9%83%A8/CMT0103%E7%8E%89%E8%A8%A3%E9%A1%9E/CMT0103ALL/CH010307%E5%85%83%E5%A7%8B%E7%84%A1%E9%87%8F%E5%BA%A6%E4%BA%BA%E4%B8%8A%E5%93%81%E5%A6%99%E7%B6%93%E8%A8%BB%E8%A7%A3/CH010307-1%E5%8D%B7%E4%B8%8A.htm"],"textual_certainty":"high"},{"dz":"DZ093","name_han":"太上洞玄灵宝无量度人上品经法（陈椿荣）","name_vi":"Thái Thượng Động Huyền Linh Bảo Vô Lượng Độ Nhân Thượng Phẩm Kinh Pháp (Trần Xuân Vinh)","bu":"洞真","author":"陈椿荣","era":"北宋末–南宋","topic":"注疏","essence":"Tập chú–giải pháp tụng Độ Nhân Kinh theo hướng nội tu và chỉ quyết. Chia đoạn chú chi tiết, kèm quẻ, đồ, phù chú và khẩu quyết. Ảnh hưởng lớn đến các chú sau như Tiêu Ứng Sẩu, Thanh Nguyên chân nhân, Trương Vũ Sơ.","key_text":"政和御注","use":"Nghiên cứu nghi tụng và pháp môn nội tu gắn với Độ Nhân.","sources":["https://zh.daoinfo.org/index.php?title=%E5%A4%AA%E4%B8%8A%E6%B4%9E%E7%8E%84%E9%9D%88%E5%AF%B6%E7%84%A1%E9%87%8F%E5%BA%A6%E4%BA%BA%E4%B8%8A%E5%93%81%E7%B6%93%E6%B3%95&variant=zh-hans","https://ctext.org/wiki.pl?if=gb&res=948278&remap=gb","http://www.ctcwri.idv.tw/CTCW-CMTS/CMT01%E6%B4%9E%E7%9C%9F%E9%83%A8/CMT0103%E7%8E%89%E8%A8%A3%E9%A1%9E/CMT0103ALL/CH010308%E5%A4%AA%E4%B8%8A%E6%B4%9E%E7%8E%84%E9%9D%88%E5%AF%B6%E7%84%A1%E9%87%8F%E5%BA%A6%E4%BA%BA%E4%B8%8A%E5%93%81%E5%A6%99%E7%B6%93%E6%B3%95/CH010308-5%E5%A4%AA%E4%B8%8A%E6%B4%9E%E7%8E%84%E9%9D%88%E5%AF%B6%E7%84%A1%E9%87%8F%E5%BA%A6%E4%BA%BA%E4%B8%8A%E5%93%81%E7%B6%93%E6%B3%95%E5%8D%B7%E4%B9%8B%E4%BA%94.htm"],"textual_certainty":"high"},{"dz":"DZ113","name_han":"黄帝阴符经解（蹇昌辰）","name_vi":"Hoàng Đế Âm Phù Kinh Giải (Kiển Xương Thần)","bu":"洞真","author":"蹇昌辰","era":"北宋","topic":"注疏","essence":"Giải Âm Phù theo hư tĩnh tự nhiên của Lão học, kết hợp dưỡng sinh và cơ trời–việc người. Dùng bản hơn bốn trăm chữ, chia chương; cho rằng ba trăm lời do Huyền Nữ trao, trăm lời do Hoàng Đế diễn. Nhấn mạnh “lý quy ư tự đắc”.","key_text":"藏微隐妙，该天括地，其经简，其义深，理归于自得者也。","use":"Đọc Âm Phù theo hướng triết–dưỡng sinh Bắc Tống.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E8%A7%A3%EF%BC%88%E8%B9%87%E6%98%8C%E8%BE%B0%EF%BC%89&variant=zh-hans","https://zh.wikisource.org/wiki/%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E8%A7%A3","http://simple.taolibrary.com/category/category94/c94015.htm"],"textual_certainty":"high"},{"dz":"DZ114","name_han":"黄帝阴符经注解（任照一）","name_vi":"Hoàng Đế Âm Phù Kinh Chú Giải (Nhậm Chiếu Nhất)","bu":"洞真","author":"任照一","era":"北宋","topic":"注疏","essence":"Chú bản ba trăm chữ, không chia chương; định nghĩa “âm” là ẩn, “phù” là hợp, tức thiên đạo và nhân đạo ngầm khớp. Lấy “quan thiên chi đạo, chấp thiên chi hành” làm cương lĩnh tu hành và dụng thế.","key_text":"阴者，暗也；符者，合也。","use":"Hiểu khung thiên–nhân hợp nhất của Âm Phù.","sources":["https://www.shidianguji.com/book/DZ0114","https://ctext.org/wiki.pl?if=gb&chapter=584390&remap=gb","https://zh.wikisource.org/zh-hans/%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93"],"textual_certainty":"high"},{"dz":"DZ115","name_han":"黄帝阴符经注（黄居真）","name_vi":"Hoàng Đế Âm Phù Kinh Chú (Hoàng Cư Chân)","bu":"洞真","author":"黄居真","era":"宋","topic":"注疏","essence":"Chú Âm Phù một quyển trong Động chân bộ ngọc quyết loại. Giải theo mạch đạo gia dụng cơ và tu thân, bổ sung dải chú Tống đại cạnh Kiển Xương Thần và Nhậm Chiếu Nhất.","key_text":"观天之道，执天之行，尽矣。","use":"Đối chiếu chú Tống về Âm Phù.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E8%A8%BB%EF%BC%88%E9%BB%83%E5%B1%85%E7%9C%9F%EF%BC%89&variant=zh-hans","https://baike.baidu.com/item/%E9%81%93%E8%97%8F%E7%9B%AE%E5%BD%95/1989063","https://a.daorenjia.com/c17"],"textual_certainty":"high"},{"dz":"DZ116","name_han":"黄帝阴符经注（沈亚夫）","name_vi":"Hoàng Đế Âm Phù Kinh Chú (Thẩm Á Phu)","bu":"洞真","author":"沈亚夫","era":"北宋","topic":"注疏","essence":"Chú chia ba chương, cùng dòng với các chú Tống lấy cơ trời–đạo thuật làm trục. Thường được in chung hệ với chú Thái thị; nhấn mạnh động tĩnh và dụng cơ.","key_text":"天性，人也；人心，机也。","use":"So sánh chú chia chương với các bản không chia chương.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E6%B3%A8%EF%BC%88%E6%B2%88%E4%BA%9E%E5%A4%AB%EF%BC%89&variant=zh-hans","http://www.taolibrary.com/category/category94/c94003.htm","https://zh.wikisource.org/zh-hans/%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93"],"textual_certainty":"high"},{"dz":"DZ118","name_han":"黄帝阴符经解义（萧真宰）","name_vi":"Hoàng Đế Âm Phù Kinh Giải Nghĩa (Tiêu Chân Tể)","bu":"洞真","author":"萧真宰","era":"宋","topic":"注疏","essence":"Giải nghĩa theo lối nghĩa lý sâu, dùng hình ảnh “tam đạo” (trời–vật–người) và phân biệt tặc/đạo để bàn dưỡng tính toàn chân. Bản hiện tồn khuyết chú thượng chương nhưng vẫn là chú sớ quan trọng thời Tống.","key_text":"盖养性全真之道，在于无失其则而已。","use":"Đọc Âm Phù theo hướng nghĩa lý và đạo sinh.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E8%A7%A3%E7%BE%A9%EF%BC%88%E8%95%AD%E7%9C%9F%E5%AE%B0%EF%BC%89&variant=zh-hans","https://ctext.org/wiki.pl?if=gb&chapter=787120&remap=gb","https://zh.wikisource.org/wiki/%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E8%A7%A3%E7%BE%A9"],"textual_certainty":"high"},{"dz":"DZ119","name_han":"阴符经三皇玉诀（原题轩辕黄帝）","name_vi":"Âm Phù Kinh Tam Hoàng Ngọc Quyết (nguyên đề Hiên Viên Hoàng Đế)","bu":"洞真","author":"金人託名轩辕黄帝（广成子、天真皇人答问体）","era":"金","topic":"注疏","essence":"Hình thức vấn đáp: Hoàng Đế hỏi, Quảng Thành Tử và Thiên Chân Hoàng Nhân giải. Chia ba quyển Thiên–Địa–Nhân hoàng, cốt lõi luyện tinh khí thần và nội đan trường sinh. Là chú sớ giả thác nhưng có mặt trong Đạo tạng và được dẫn từ đời Kim.","key_text":"观天之道，执天之行，尽矣。","use":"Nghiên cứu Âm Phù theo khung tam hoàng và nội đan.","sources":["https://zh.daoinfo.org/index.php?title=%E9%99%B0%E7%AC%A6%E7%B6%93%E4%B8%89%E7%9A%87%E7%8E%89%E8%A8%A3%EF%BC%88%E5%8E%9F%E9%A1%8C%E8%BB%92%E8%BD%85%E9%BB%83%E5%B8%9D%EF%BC%89&variant=zh-hans","https://zh.wikisource.org/zh-hans/%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93"],"textual_certainty":"high"},{"dz":"DZ121","name_han":"黄帝阴符经注（唐淳）","name_vi":"Hoàng Đế Âm Phù Kinh Chú (Đường Thuần)","bu":"洞真","author":"唐淳（金陵道人）","era":"宋金之际","topic":"注疏","essence":"Dùng bản khoảng năm trăm chữ, chia ba chương; trước dẫn tiền nhân, sau phụ kiến riêng, chủ nội đan. Có tự năm Chính Đại Kỷ Sửu (1229), phản ánh dòng chú toàn chân–nội đan.","key_text":"观天之道，执天之行，尽矣。","use":"Đọc Âm Phù theo nội đan Tống–Kim.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E6%B3%A8%EF%BC%88%E5%94%90%E6%B7%B3%EF%BC%89&variant=zh-hans","https://zh.wikisource.org/zh-hans/%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93"],"textual_certainty":"high"},{"dz":"DZ126","name_han":"黄帝阴符经夹颂解注（王道渊）","name_vi":"Hoàng Đế Âm Phù Kinh Giáp Tụng Giải Chú (Vương Đạo Uyên)","bu":"洞真","author":"王道渊（王玠，混然子）","era":"元","topic":"注疏","essence":"Chú kèm tụng, lấy âm dương–thái cực làm then chốt giải “âm phù”. Bản hơn bốn trăm chữ, chia quyển không chia chương; kết hợp giải nghĩa và kệ tụng để truyền nội đan.","key_text":"夫阴符者，一阴一阳之谓也。","use":"Tu và tụng Âm Phù theo dòng hỗn nhiên tử.","sources":["https://zh.daoinfo.org/index.php?title=%E9%BB%83%E5%B8%9D%E9%99%B0%E7%AC%A6%E7%B6%93%E5%A4%BE%E9%A0%8C%E8%A7%A3%E8%A8%BB%EF%BC%88%E7%8E%8B%E9%81%93%E6%B7%B5%EF%BC%89&variant=zh-hans","http://www.taolibrary.com/category/category94/c94009.htm","https://a.daorenjia.com/daozang17-758"],"textual_certainty":"high"},{"dz":"DZ396","name_han":"洞玄灵宝自然九天生神玉章经解（王希巢）","name_vi":"Động Huyền Linh Bảo Tự Nhiên Cửu Thiên Sinh Thần Ngọc Chương Kinh Giải (Vương Hy Sào)","bu":"洞玄","author":"王希巢","era":"南宋（开禧元年，1205）","topic":"注疏","essence":"Giải Cửu Thiên Sinh Thần Chương theo bốn yếu: ái hình, bảo thần, quý khí, cố căn (tinh). Liên hệ hình–thần–khí–tinh như mạng sống không thể rời; chú cả tiền bán và sinh thần cửu chương.","key_text":"九天生神章大要有四：一曰爱其形，二曰保其神，三曰贵其气，四曰固其根。","use":"Tu sinh thần và hiểu cốt tủy Linh Bảo sinh thần.","sources":["https://zh.daoinfo.org/index.php?title=%E6%B4%9E%E7%8E%84%E9%9D%88%E5%AF%B6%E8%87%AA%E7%84%B6%E4%B9%9D%E5%A4%A9%E7%94%9F%E7%A5%9E%E7%8E%89%E7%AB%A0%E7%B6%93%E8%A7%A3&variant=zh-hans","https://ctext.org/wiki.pl?if=gb&chapter=398415","https://zh.wikisource.org/wiki/%E6%B4%9E%E7%8E%84%E9%9D%88%E5%AF%B6%E8%87%AA%E7%84%B6%E4%B9%9D%E5%A4%A9%E7%94%9F%E7%A5%9E%E7%AB%A0%E7%B6%93"],"textual_certainty":"high"},{"dz":"DZ750","name_han":"太上老君说常清静经注（无名氏）","name_vi":"Thái Thượng Lão Quân Thuyết Thường Thanh Tịnh Kinh Chú (Vô danh thị)","bu":"洞神","author":"无名氏","era":"宋–元","topic":"注疏","essence":"Chú–luận kết hợp thanh tĩnh tu tính và nội đan; khẳng định trì tụng phải đi với trai giới và luyện dưỡng. Kèm chuyện linh nghiệm đời Đường (Đồng Xương công chúa…) để tuyên dương thần nghiệm của kinh.","key_text":"大道无形，生育天地；大道无情，运行日月。","use":"Công khóa thanh tĩnh và đối chiếu các chú khác.","sources":["https://zh.daoinfo.org/index.php?title=%E5%A4%AA%E4%B8%8A%E8%80%81%E5%90%9B%E8%AA%AA%E5%B8%B8%E6%B8%85%E9%9D%9C%E7%B6%93%E8%A8%BB%EF%BC%88%E7%84%A1%E5%90%8D%E6%B0%8F%EF%BC%89&variant=zh-hans","https://zh.wikisource.org/zh-hans/%E5%A4%AA%E4%B8%8A%E8%80%81%E5%90%9B%E8%AA%AA%E5%B8%B8%E6%B8%85%E9%9D%9C%E7%B6%93%E8%A8%BB_(%E7%84%A1%E5%90%8D%E6%B0%8F%E8%A8%BB)","https://ctext.org/wiki.pl?if=gb&res=878176"],"textual_certainty":"high"},{"dz":"DZ752","name_han":"太上老君说常清静经注（王元晖）","name_vi":"Thái Thượng Lão Quân Thuyết Thường Thanh Tịnh Kinh Chú (Vương Nguyên Huy)","bu":"洞神","author":"王元晖（白玉蟾分章正误）","era":"元（皇庆元年前后）","topic":"注疏","essence":"Dựa bản Bạch Ngọc Thiềm chia năm chương (tiên thiên đại đạo, tạo hóa tự nhiên…), chú bằng ngữ nội đan và đồ giải. Giải Thanh Tĩnh Kinh thành khẩu quyết tu tâm hợp đạo, không chỉ nghĩa văn.","key_text":"太者，无也；上者，极也；说者，开化也。常清静者，虚无大道，自然生成。","use":"Tu tính–mệnh qua Thanh Tĩnh theo Nam tông–toàn chân.","sources":["https://zh.daoinfo.org/index.php?title=%E5%A4%AA%E4%B8%8A%E8%80%81%E5%90%9B%E8%AA%AA%E5%B8%B8%E6%B8%85%E9%9D%9C%E7%B6%93%E8%A8%BB%EF%BC%88%E7%8E%8B%E5%85%83%E6%9A%89%EF%BC%89&variant=zh-hans","https://www.shidianguji.com/zh/book/DZ0757","https://ctext.org/library.pl?if=gb&res=84436&remap=gb"],"textual_certainty":"high"},{"dz":"DZ968","name_han":"太上老君说常清静经颂注（刘通微）","name_vi":"Thái Thượng Lão Quân Thuyết Thường Thanh Tịnh Kinh Tụng Chú (Lưu Thông Vi)","bu":"洞神","author":"刘通微（默然子）","era":"金","topic":"注疏","essence":"Chú bằng ngũ ngôn tụng, dung hợp đạo–thiền: trừng tâm khiển dục, thanh tĩnh thường tịch. Khuyên bỏ tham sân si, tu giới định tuệ để lục dục bất sinh. Thể loại tụng chú khác hẳn các chú văn xuôi.","key_text":"大道无形，生育天地。","use":"Tụng niệm và tu tâm theo lối toàn chân.","sources":["https://zh.daoinfo.org/index.php?title=%E5%A4%AA%E4%B8%8A%E8%80%81%E5%90%9B%E8%AA%AA%E5%B8%B8%E6%B8%85%E9%9D%9C%E7%B6%93%E9%A0%8C%E8%A8%BB%EF%BC%88%E5%8A%89%E9%80%9A%E5%BE%AE%EF%BC%89&variant=zh-hans","http://www.ctcwri.idv.tw/CTCW-CMTS/CMT03%E6%B4%9E%E7%A5%9E%E9%83%A8/CMT0311%E8%AE%9A%E9%A0%8C%E9%A1%9E/CMT0311ALL/CH031101%E5%A4%AA%E4%B8%8A%E8%80%81%E5%90%9B%E8%AA%AA%E5%B8%B8%E6%B8%85%E9%9D%9C%E7%B6%93%E9%A0%8C%E8%A8%BB/CH031101-1%E5%A4%AA%E4%B8%8A%E8%80%81%E5%90%9B%E8%AA%AA%E5%B8%B8%E6%B8%85%E9%9D%9C%E7%B6%93%E9%A0%8C%E8%A8%BB.htm","https://ctext.org/wiki.pl?if=gb&res=876387&remap=gb"],"textual_certainty":"high"}]}
